-- TEST ONLY. Emulates what a Supabase project already provides before our migrations run,
-- so RLS tests on plain Postgres exercise the same roles, auth helpers and default grants.
-- Never apply this to a real Supabase project (it already has all of this).
--
-- Mirrors Supabase:
--   * roles anon / authenticated / service_role (service_role bypasses RLS);
--   * schema auth with auth.users and auth.uid() / auth.jwt() / auth.role(), which read the
--     JWT claims from the `request.jwt.claims` setting (as PostgREST sets them);
--   * default privileges that GRANT ALL on new public tables to anon and authenticated.
--     Our migrations must revoke these; the tests prove they do.

create role anon nologin noinherit;
create role authenticated nologin noinherit;
create role service_role nologin noinherit bypassrls;
grant anon, authenticated, service_role to postgres;

create schema auth;
grant usage on schema auth to anon, authenticated, service_role;

create table auth.users (
  id uuid primary key,
  email text,
  raw_user_meta_data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create function auth.jwt() returns jsonb
language sql stable
as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')
  )::jsonb
$$;

create function auth.uid() returns uuid
language sql stable
as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.sub', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')
  )::uuid
$$;

create function auth.role() returns text
language sql stable
as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role')
  )::text
$$;

grant usage on schema public to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema public grant all on functions to anon, authenticated, service_role;
